// Find the axis with smallest absolute component to minimize numerical error
T absX = std::abs(v1.x);
T absY = std::abs(v1.y);
T absZ = std::abs(v1.z);
int minAxis;
if (absX < absY && absX < absZ) {
    minAxis = 0;
} else if (absY < absZ) {
    minAxis = 1;
} else {
    minAxis = 2;
}

// Create a temporary vector perpendicular to v1 by crossing with a basis vector
Vector3<T> tmp;
if (minAxis == 0) {
    tmp = Vector3<T>(1, 0, 0);
} else if (minAxis == 1) {
    tmp = Vector3<T>(0, 1, 0);
} else {
    tmp = Vector3<T>(0, 0, 1);
}

// Use cross product to get perpendicular vectors
*v2 = Cross(v1, tmp).Normalized();
*v3 = Cross(v1, *v2).Normalized();

